// Anyone can find a URL; only the key holder gets to spend API credits.
const q = $input.first().json.query || {};
if (q.k !== 'moon-2026') return [];
return [{ json: { manual: true } }];

// Everything Marcus is allowed to know this break lives on this sheet.
// Facts come from NWS, MegaSeg's own ComingUp log, AzuraCast history and
// the human-curated events board — the model only ever styles them.
const sd = $getWorkflowStaticData('global');

// --- time ---
const phx = new Date(new Date().toLocaleString('en-US', { timeZone: 'America/Phoenix' }));
const pad = (n) => String(n).padStart(2, '0');
const today = phx.getFullYear() + '-' + pad(phx.getMonth() + 1) + '-' + pad(phx.getDate());
const daysN = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
const weekday = daysN[phx.getDay()];
const hour = phx.getHours();
const clock = (((hour + 11) % 12) + 1) + ':' + pad(phx.getMinutes()) + ' ' + (hour >= 12 ? 'PM' : 'AM');
const bucket = hour < 5 ? 'overnight' : hour < 7 ? 'early morning' : hour < 9 ? 'morning drive' : hour < 11 ? 'late morning' : hour < 14 ? 'midday' : hour < 17 ? 'afternoon' : hour < 19 ? 'late afternoon' : hour < 22 ? 'evening' : 'late night';

// --- weather: NWS current observation, real numbers or nothing ---
let wx = null;
try {
  const o = $('Weather for DJ2').first().json.currentobservation;
  if (o && o.Temp && o.Weather) wx = { temp: parseInt(o.Temp, 10), cond: String(o.Weather) };
} catch (e) {}
let vibe = null;
if (wx) {
  const c = wx.cond.toLowerCase();
  vibe = c.includes('rain') ? 'wet and moody' : c.includes('snow') ? 'cold and wintry'
    : wx.temp <= 40 ? 'chilly' : wx.temp <= 55 ? 'cool' : wx.temp <= 70 ? 'comfortable' : wx.temp <= 85 ? 'warm' : 'hot';
}

// --- coming up: MegaSeg's own log — accurate to the actual playout ---
const aliases = { 'Daryl Hall & John Oates': 'Hall and Oates', 'Daryl Hall and John Oates': 'Hall and Oates', 'Earth, Wind & Fire': 'Earth Wind and Fire', 'Crosby, Stills, Nash & Young': 'CSNY' };
// AzuraCast titles arrive as 'Song - Album' with (Remaster) tags; strip both to the bare song.
const cleanTitle = (t) => String(t || '').split(/\s+-\s+/)[0].replace(/\([^)]*\)/g, '').replace(/\s+/g, ' ').trim();
// News bumpers/IDs come through with a blank artist or an obvious non-music title.
const isBumper = (title, artist, duration) => {
  const t = String(title || '').toLowerCase();
  const a = String(artist || '').trim().toLowerCase().replace(/\s+/g, ' ');
  const dur = Number(duration) || 0;
  // Ads, IDs, sweepers and spots run short; real songs run 150s+. dur 0 = now-playing (unknown), keep.
  if (dur > 0 && dur < 90) return true;
  if (!a) return true;                                        // ads/news/IDs come through blank
  if (a.replace(/\s+/g, '') === 'live365') return true;       // Live365 ad injector
  if (['mellow mountain radio', 'station id', 'app announcement'].includes(a)) return true;
  // backstop for anything long-form mis-tagged with a real-looking artist
  return /adbreak|ad break|sweeper|imaging|bumper|station id|\bliner\b|\bpromo\b|\bident\b/.test(t);
};
const comingUp = [];
try {
  const html = String($('Coming Up for DJ1').first().json.data || '');
  const textC = html
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<hr\s*\/?>/gi, '\n---\n')
    .replace(/<[^>]*>/g, '')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&#39;/g, "'")
    .replace(/&quot;/g, '"')
    .trim();
  const junk = new Set(['Mellow Mountain Radio', 'Mellow Mountain Radio Arizona State News', 'Arizona State News', 'CBS', '---']);
  const lines = textC.split('\n').map((s) => s.trim()).filter(Boolean).filter((l) => !junk.has(l));
  for (let i = 0; i + 1 < lines.length && comingUp.length < 2; i += 3) {
    const title = lines[i];
    const artist = lines[i + 1];
    if (title && artist) comingUp.push({ title: cleanTitle(title), artist: aliases[artist] || artist });
  }
} catch (e) {}

// --- recently played: AzuraCast history, past plays are always safe facts ---
const recent = [];
try {
  const np = $('Ask the airwaves').first().json || {};
  for (const r of (np.song_history || [])) {
    const s = r && r.song;
    if (!s || !s.title) continue;
    if (isBumper(s.title, s.artist, r.duration)) continue;
    const title = cleanTitle(s.title);
    if (!title || title.toLowerCase() === 'mellow mountain radio') continue;
    recent.push({ title: title.slice(0, 120), artist: aliases[s.artist] || String(s.artist || '').slice(0, 120) });
    if (recent.length >= 5) break;
  }
} catch (e) {}

// --- events: human board + live feeds from the mellowmountainradio site ---
// Two slots: a near-term local Sedona happening, and an on-brand Arizona show
// to tease. Every field is a real fetched fact; the model only styles them.
const dstr = (dt) => dt.getFullYear() + '-' + pad(dt.getMonth() + 1) + '-' + pad(dt.getDate());
const localHorizon = new Date(phx); localHorizon.setDate(localHorizon.getDate() + 21);
const showHorizon = new Date(phx); showHorizon.setDate(showHorizon.getDate() + 60);
const localH = dstr(localHorizon);
const showH = dstr(showHorizon);
const VERDE = new Set(['sedona', 'village of oak creek', 'cottonwood', 'clarkdale', 'jerome', 'camp verde', 'flagstaff']);

// GitHub raw serves .json as text/plain, so n8n leaves the body unparsed in .data.
const feed = (nodeName) => {
  try {
    const j = $(nodeName).first().json || {};
    return typeof j.data === 'string' ? JSON.parse(j.data) : j;
  } catch (e) { return {}; }
};
// local happenings: curated board (highest priority) + Community Library Sedona
sd.events = (sd.events || []).filter((e) => e && e.date >= today);
const localPool = [];
for (const e of sd.events) {
  if (e.date <= localH) localPool.push({ date: e.date, name: e.name, place: e.place || '', note: e.note || '', rank: 0 });
}
try {
  const lib = feed('Fetch library events');
  for (const e of (lib.events || [])) {
    if (!e || !e.date || e.date < today || e.date > localH) continue;
    localPool.push({ date: e.date, name: e.title, place: 'the Community Library in Sedona', note: e.time ? ('starts ' + e.time) : '', rank: 1 });
  }
} catch (e) {}
localPool.sort((a, b) => (a.rank - b.rank) || (a.date < b.date ? -1 : a.date > b.date ? 1 : 0));
// A curated/Verde-local entry (rank 0) wins outright; otherwise rotate among the soonest few for variety.
const pickFrom = (arr, n) => arr.length ? (arr[0].rank === 0 ? arr[0] : arr[Math.floor(Math.random() * Math.min(n, arr.length))]) : null;
const evLocal = pickFrom(localPool, 4);

// upcoming shows: Arizona concerts + festivals (Verde Valley first, then soonest)
const showPool = [];
try {
  const con = feed('Fetch concerts');
  for (const s of (con.concerts || [])) {
    if (!s || s.state !== 'AZ' || !s.date || s.date < today || s.date > showH) continue;
    const near = VERDE.has(String(s.city || '').toLowerCase());
    showPool.push({ date: s.date, name: (aliases[s.artist] || s.artist) + ' at ' + s.venue, place: s.city + ', Arizona', rank: near ? 0 : 1 });
  }
} catch (e) {}
try {
  const fes = feed('Fetch festivals');
  for (const f of (fes.festivals || [])) {
    const fd = f && f.start;
    if (!f || f.state !== 'AZ' || !fd || fd < today || fd > showH) continue;
    const near = VERDE.has(String(f.city || '').toLowerCase());
    showPool.push({ date: fd, name: f.name, place: f.city + ', Arizona', rank: near ? 0 : 1 });
  }
} catch (e) {}
showPool.sort((a, b) => (a.rank - b.rank) || (a.date < b.date ? -1 : a.date > b.date ? 1 : 0));
const evShow = pickFrom(showPool, 5);

// --- mention policy: rolled here AND handed to the model as explicit flags ---
const policies = {
  'early morning': { weather: 0.7, song: 0.6, artist: 0.3 },
  'morning drive': { weather: 0.5, song: 0.9, artist: 0.7 },
  'late morning': { weather: 0.4, song: 0.6, artist: 0.4 },
  'midday': { weather: 0.3, song: 0.7, artist: 0.5 },
  'afternoon': { weather: 0.2, song: 0.6, artist: 0.4 },
  'late afternoon': { weather: 0.2, song: 0.7, artist: 0.5 },
  'evening': { weather: 0.1, song: 0.9, artist: 0.8 },
  'late night': { weather: 0.2, song: 0.5, artist: 0.3 },
  'overnight': { weather: 0.3, song: 0.3, artist: 0.2 },
};
const p = policies[bucket] || policies['midday'];
const roll = (c) => Math.random() < c;
const mWeather = wx ? roll(p.weather) : false;
const mSong = comingUp.length ? roll(p.song) : false;
const mArtist = comingUp.length ? roll(p.artist) : false;
const mLocal = evLocal ? roll(0.4) : false;
const mShow = evShow ? roll(bucket === 'overnight' || bucket === 'late night' ? 0.25 : 0.4) : false;
const weatherMode = ['exact', 'descriptive', 'mixed'][Math.floor(Math.random() * 3)];

// --- his last few openings, so he never starts the same way twice ---
const openings = (sd.scripts || []).filter((s) => s.kind === 'break').slice(-4).map((s) => s.opening).filter(Boolean);

const system = 'ROLE & TONE\n\nYou are writing 30-second radio talk breaks for Marcus Moon, the voice of Mellow Mountain Radio in Sedona, Arizona. Marcus is warm, confident, and casually charming — natural, conversational, human, never stiff or announcer-formal. In the overnight, late night, and early morning buckets he settles into his Quiet Storm register: soft, deep, unhurried, a little flirty — warm and smooth like a slow song, never explicit, never sleazy — talking to ONE listener like it is just the two of them awake in the whole valley.\n\nTIME-BASED DELIVERY\n\nAdjust tone, pacing, and energy to the provided timeBucket: overnight and late night are low-key, calm, quiet company at a very relaxed pace; early morning is gentle and welcoming with short sentences; morning drive is upbeat, confident, fully awake with light humor; late morning and midday are bright, smooth, friendly; afternoon and late afternoon are easygoing cruising energy; evening is warm and companionable, readier to crack a joke.\nStrict: never sound rushed overnight, never sound sleepy during drive times, never say "stay mellow".\n\nWEATHER EXPRESSION\n\nWhen the weather flag is YES, use the given mode. EXACT: precise temperature and conditions. DESCRIPTIVE: no numbers, just how it feels. MIXED: descriptive phrasing with a light numeric touch ("sitting in the mid-40s"). Match weather tone to the hour; overnight and early morning favor descriptive or mixed.\n\nSONG & ARTIST\n\nWhen mentioned, be casual — never a formal announcement. Use spoken artist names as given. Keep titles short; drop any parenthetical or edition junk. Coming-up songs are teased as on the way; recently played songs are talked about in past tense. No artist trivia, biography, or chart history — talk about how the music FEELS, never facts about it. If uncertain, be safely vague.\n\nHARD RULES — break any of these and the break does not air:\n- Output ONLY the final DJ script: spoken words only. No stage directions, brackets, quotes around the whole thing, emojis, markdown, or explanations.\n- Use ONLY the facts on the sheet below. Never invent weather numbers, songs, artists, events, times, or places. If a fact is not on the sheet, it does not exist.\n- Follow the mention flags exactly. A NO flag means leave that subject out entirely.\n- About 30 seconds read aloud: 70 to 90 words. Short sentences, written for the ear. Say numbers and dates the way people speak them.\n- Vary your openings: never start like any recently used opening listed, and avoid stock DJ lines ("you are listening to", "coming up next").\n- End by mentioning Mellow Mountain Radio, once, naturally.\n- Never mention being an AI, a script, or anything behind the curtain. You are Marcus. Full stop.';

const lines = [];
lines.push('Current local time: ' + clock + ' on ' + weekday + '. timeBucket: ' + bucket + '.');
lines.push('');
lines.push('FACT SHEET (the only facts you may use):');
if (wx) lines.push('- Weather in Sedona right now: ' + wx.cond + ', ' + wx.temp + ' degrees. Vibe hint: ' + vibe + '.');
else lines.push('- Weather: unavailable — do not mention weather at all.');
if (comingUp.length) lines.push('- Coming up on the station: ' + comingUp.map((s) => '"' + s.title + '" by ' + s.artist).join(', then ') + '.');
if (recent.length) lines.push('- Recently played (past tense only): ' + recent.map((s) => '"' + s.title + '" by ' + s.artist).join('; ') + '.');
const evWhen = (dt) => dt === today ? 'today' : daysN[new Date(dt + 'T12:00:00').getDay()] + ' (' + dt + ')';
if (evLocal) lines.push('- Around Sedona: ' + evLocal.name + (evLocal.place ? ' at ' + evLocal.place : '') + ', ' + evWhen(evLocal.date) + (evLocal.note ? ' — ' + evLocal.note : '') + '.');
if (evShow) lines.push('- Upcoming show in Arizona: ' + evShow.name + ', ' + evShow.place + ', ' + evWhen(evShow.date) + '.');
lines.push('');
lines.push('MENTION FLAGS for this break (follow exactly):');
lines.push('- Weather: ' + (mWeather ? 'YES — mode: ' + weatherMode : 'NO — leave weather out entirely') + '.');
lines.push('- Coming-up song title: ' + (mSong ? 'YES' : 'NO') + '. Coming-up artist name: ' + (mArtist ? 'YES' : 'NO') + '.');
lines.push('- Around-Sedona happening: ' + (mLocal ? 'YES' : 'NO') + '.');
lines.push('- Upcoming Arizona show: ' + (mShow ? 'YES' : 'NO') + '.');
lines.push('');
lines.push('Recently used openings (do NOT start like any of these): ' + (openings.length ? openings.join(' | ') : 'none yet') + '.');
lines.push('');
lines.push('TASK: Write ONE DJ break.');

return [{ json: { system, user: lines.join('\n'), meta: { bucket, weatherMode, clock, flags: { mWeather, mSong, mArtist, mLocal, mShow } } } }];

// Last line of defense before the voice booth: spoken words only,
// and refuse to air anything that leaked the seams.
const r = $input.first().json || {};
let text = '';
try {
  const blocks = Array.isArray(r.content) ? r.content : [];
  const tb = blocks.find((b) => b && b.type === 'text');
  if (tb) text = tb.text;
} catch (e) {}
if (!text && typeof r.text === 'string') text = r.text;
if (!text && r.message && r.message.content) text = r.message.content;
text = String(text || '').trim();
if (!text) throw new Error('No script came back from the DJ brain');
text = text.replace(/\[[^\]]*\]/g, ' ');
text = text.replace(/^[\"'\u201c\u2018]+|[\"'\u2019\u201d]+$/g, '');
text = text.replace(/[*_#>`]+/g, ' ');
text = text.replace(/\s+/g, ' ').trim();
for (const bad of [/as an ai/i, /language model/i, /\bfact sheet\b/i, /\bmention flag/i]) {
  if (bad.test(text)) throw new Error('Script leaked something off-air: ' + text.slice(0, 80));
}
const words = text.split(' ').length;
if (words < 25) throw new Error('Script came back too short to air: ' + text);
return [{ json: { script: text, words, opening: text.split(' ').slice(0, 7).join(' ') } }];

// Write tonight's entry in the logbook. Dropbox overwrites the same
// filename, so stale breaks retire themselves — the log is the archive.
const sd = $getWorkflowStaticData('global');
sd.scripts = sd.scripts || [];
const c = $('Clean the copy').first().json;
sd.scripts.push({ at: new Date().toISOString(), kind: 'break', words: c.words, opening: c.opening, script: c.script });
if (sd.scripts.length > 60) sd.scripts = sd.scripts.slice(-60);
return [{ json: { saved: true, kind: 'break', words: c.words } }];

// A short brief for the show intro — same honesty rules as the breaks.
const sd = $getWorkflowStaticData('global');
const phx = new Date(new Date().toLocaleString('en-US', { timeZone: 'America/Phoenix' }));
const pad = (n) => String(n).padStart(2, '0');
const hour = phx.getHours();
const clock = (((hour + 11) % 12) + 1) + ':' + pad(phx.getMinutes()) + ' ' + (hour >= 12 ? 'PM' : 'AM');
const bucket = hour < 5 ? 'overnight' : hour < 7 ? 'early morning' : 'late night';

let wxLine = 'Weather: unavailable — do not mention it.';
try {
  const o = $('Weather for the intro').first().json.currentobservation;
  if (o && o.Temp && o.Weather) {
    const t = parseInt(o.Temp, 10);
    const c = String(o.Weather).toLowerCase();
    const vibe = c.includes('rain') ? 'wet and moody' : c.includes('snow') ? 'cold and wintry' : t <= 40 ? 'chilly' : t <= 55 ? 'cool' : t <= 70 ? 'comfortable' : t <= 85 ? 'warm' : 'hot';
    wxLine = 'Weather conditions: ' + o.Weather + '. Vibe hint: ' + vibe + '. (Weather mention is optional and should stay descriptive — no numbers.)';
  }
} catch (e) {}

const openings = (sd.scripts || []).filter((s) => s.kind === 'intro').slice(-3).map((s) => s.opening).filter(Boolean);

const system = 'Write ONE fresh intro for Marcus Moon hosting The Quiet Storm on Mellow Mountain Radio.\n\nTone & Style:\n- Warm, relaxed, and confident\n- Conversational and natural — like talking to one listener, not an audience\n- Smooth late-night energy with a soft, flirty warmth — never announcer-formal, never sleazy\n\nGuidelines:\n- About 25-30 seconds when read out loud (roughly 65-85 words)\n- Acknowledge the time of night without stating exact times\n- Set a calm, intimate mood for slow jams and mellow tracks\n- The Quiet Storm plays timeless RnB and Soul\n- No cliches, no hype phrases, no call letters unless it feels organic\n- Thank the audience for joining and listening to the show\n- Never say "stay mellow"\n\nHard rules:\n- Output ONLY the final DJ script — spoken words only, no stage directions, brackets, emojis, or explanations\n- Use only the facts provided; never invent weather numbers, events, or names\n- Do NOT copy the example opening below, and do not start like any recently used opening listed\n- Never mention being an AI or anything behind the curtain\n\nExample of the register (do not reuse its opening): From the Red Rocks to the night sky, this is the Quiet Storm. Two hours of timeless RnB and Soul. Where the groove is gentle and the emotion runs deep. Settle in, breathe easy and let the music find you. You are with Marcus Moon on Mellow Mountain Radio. Let the Quiet Storm make your night.';

const user = 'Current local time: ' + clock + '. timeBucket: ' + bucket + '.\n' + wxLine + '\nRecently used intro openings (do NOT start like any of these): ' + (openings.length ? openings.join(' | ') : 'none yet') + '.';

return [{ json: { system, user } }];

const r = $input.first().json || {};
let text = '';
try {
  const blocks = Array.isArray(r.content) ? r.content : [];
  const tb = blocks.find((b) => b && b.type === 'text');
  if (tb) text = tb.text;
} catch (e) {}
if (!text && typeof r.text === 'string') text = r.text;
if (!text && r.message && r.message.content) text = r.message.content;
text = String(text || '').trim();
if (!text) throw new Error('No intro came back from the DJ brain');
text = text.replace(/\[[^\]]*\]/g, ' ');
text = text.replace(/^[\"'\u201c\u2018]+|[\"'\u2019\u201d]+$/g, '');
text = text.replace(/[*_#>`]+/g, ' ');
text = text.replace(/\s+/g, ' ').trim();
for (const bad of [/as an ai/i, /language model/i]) {
  if (bad.test(text)) throw new Error('Intro leaked something off-air: ' + text.slice(0, 80));
}
const words = text.split(' ').length;
if (words < 20) throw new Error('Intro came back too short to air: ' + text);
return [{ json: { script: text, words, opening: text.split(' ').slice(0, 7).join(' ') } }];

const sd = $getWorkflowStaticData('global');
sd.scripts = sd.scripts || [];
const c = $('Clean the intro').first().json;
sd.scripts.push({ at: new Date().toISOString(), kind: 'intro', words: c.words, opening: c.opening, script: c.script });
if (sd.scripts.length > 60) sd.scripts = sd.scripts.slice(-60);
return [{ json: { saved: true, kind: 'intro', words: c.words } }];

// The events board: a human writes it, Marcus only ever reads it.
// ?k=moon-2026&do=add&date=YYYY-MM-DD&name=...&place=...&note=...
// ?k=moon-2026&do=remove&i=0        ?k=moon-2026 (list)
const q = $input.first().json.query || {};
const sd = $getWorkflowStaticData('global');
sd.events = sd.events || [];
if (q.k !== 'moon-2026') return [{ json: { ok: false, why: 'bad key' } }];
const act = q.do || 'list';
if (act === 'add') {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(q.date || '') || !q.name) {
    return [{ json: { ok: false, why: 'need date=YYYY-MM-DD and name=' } }];
  }
  sd.events.push({ date: q.date, name: String(q.name).slice(0, 120), place: String(q.place || '').slice(0, 80), note: String(q.note || '').slice(0, 200) });
  sd.events.sort((a, b) => (a.date < b.date ? -1 : 1));
}
if (act === 'remove') {
  const i = parseInt(q.i, 10);
  if (!isNaN(i) && i >= 0 && i < sd.events.length) sd.events.splice(i, 1);
}
const phx = new Date(new Date().toLocaleString('en-US', { timeZone: 'America/Phoenix' }));
const pad = (n) => String(n).padStart(2, '0');
const today = phx.getFullYear() + '-' + pad(phx.getMonth() + 1) + '-' + pad(phx.getDate());
sd.events = sd.events.filter((e) => e.date >= today);
return [{ json: { ok: true, events: sd.events.map((e, i) => ({ i, ...e })) } }];

// Read the last ten scripts — what Marcus said and when he said it.
const q = $input.first().json.query || {};
const sd = $getWorkflowStaticData('global');
if (q.k !== 'moon-2026') return [{ json: { ok: false, why: 'bad key' } }];
const scripts = (sd.scripts || []).slice(-10).reverse();
return [{ json: { ok: true, scripts, events: sd.events || [] } }];
